(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0020.js"] = [{"id":"glyph-seal-6574","script":"seal","character":"整","reading":"zhěng","description":"zhěng：(1)有秩序，不乱～齐。～洁。～然有序。\n(2)治理～治。～改。～编。～饬（ａ．使有条理，整顿；ｂ．整齐，有条理）。～装待发。\n(3)修理，修饰～形。～旧如新。\n(4)完全无缺，没有零头～体。完～。\n(5)使人吃苦头～人。\n(6)搞，弄咋～的？","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-整"},{"id":"glyph-seal-6577","script":"seal","character":"敷","reading":"fū","description":"fū：(1)布置，铺开，摆开～设。～陈（铺陈，详细叙述）。～衍（ａ．叙述并发挥，亦作敷演”；ｂ．做事不够负责或待人不恳切，只做表面上的应付；ｃ．勉强维持）。\n(2)涂上，搽上～药。～粉。\n(3)足够入不～出。\n(4)古同肤”，表面的。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敷"},{"id":"glyph-seal-6587","script":"seal","character":"文","reading":"wén","description":"wén：(1)事物错综所造成的纹理或形象灿若～锦。\n(2)刺画花纹～身。\n(3)记录语言的符号～字。～盲。以～害辞。\n(4)用文字记下来以及与之有关的～凭。～艺。～体。～典。～苑。～献（指有历史价值和参考价值的图书资料）。～采（ａ．文辞、文艺方面的才华；ｂ．错杂艳丽的色彩）。\n(5)人类劳动成果的总结～化。～物。\n(6)自然界的某些现象天～。水～。\n(7)旧时指礼节仪式虚～。繁～缛节（过多的礼节仪式）。\n(8)文华辞采，与质”、情”相对～质彬彬。\n(9)温和～火。～静。～雅。\n(10)指非军事的～职。～治武功（指礼乐教化和军事功绩）。\n(11)指以古汉语为基础的书面语～言。～白间杂。\n(12)专指社会科学～科。\n(13)掩饰～过饰非。\n(14)量词，指旧时小铜钱一～不名。\n(15)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-文"},{"id":"glyph-seal-658b","script":"seal","character":"斋","reading":"zhāi","description":"遂许斋五日\n秦王斋五日。\n进食\n⒈迷信者祭祀前整洁身心～祭。～戒沐浴。〈引〉信奉佛教、道教等人吃的素食吃～。\n⒉施舍饭食给僧人～僧。\n⒊书房或学舍或某些商店名称书～。东～。荣宝～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斋"},{"id":"glyph-seal-658c","script":"seal","character":"斌","reading":"bīn","description":"bīn：〔～～〕同彬彬”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斌"},{"id":"glyph-seal-6590","script":"seal","character":"斐","reading":"fěi；fēi","description":"fēi：有文彩的～然（ａ．有文彩的样子，如～～成章”；ｂ．显著，如成绩～～”）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斐"},{"id":"glyph-seal-6597","script":"seal","character":"斗","reading":"dòu；dǒu","description":"dǒu：(1)中国市制容量单位（十升为一斗，十斗为一石）～酒只鸡（经常用作招待客人的简单酒食，家常便饭）。\n(2)量粮食的器具～筲之人（形容人器量狭小，见识短浅）。\n(3)形容小东西的大～胆。\n(4)形容大东西的小～室。\n(5)像斗的东西～车。～笠。～篷。熨～。\n(6)星名，二十八宿之一，亦泛指星南～。气冲～牛（怒气冲天）。\n(7)特指北斗星”～折蛇行。\n(8)古同陡”，高耸的样子。\n(9)古同陡”，突然。\n〔斗拱〕（枓栱）拱是建筑上弧形承重结构，斗是垫拱的方木块，合称斗拱。\n（魕）\ndòu：(1)对打～殴。战～。\n(2)比赛胜负，争胜～力。～劲。～智。～志昂扬。\n(3)使动物之间互争高下～牛。～蟋蟀。\n(4)拼合，对准，凑近～眼。\n(5)古同逗”，逗引。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斗"},{"id":"glyph-seal-6599","script":"seal","character":"料","reading":"liào","description":"liào：(1)估计，猜想～想。预～。\n(2)可供制造其他东西的物质材～。～子。备～。\n(3)喂牲口用的谷物草～。\n(4)一种熔点较低的玻璃，用来制造器皿或工艺品～器。\n(5)烹调时的调味品调～。\n(6)整理，处理～理。\n(7)量词，用于中药配制丸药，处方剂量的全份配一～药。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-料"},{"id":"glyph-seal-659b","script":"seal","character":"斛","reading":"hú","description":"hú：中国旧量器名，亦是容量单位，一斛本为十斗，后来改为五斗。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斛"},{"id":"glyph-seal-659c","script":"seal","character":"斜","reading":"xié","description":"xié：不正，跟平面或直线既不平行也不垂直的～坡。～面。～度。～线。～视。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斜"},{"id":"glyph-seal-659f","script":"seal","character":"斟","reading":"zhēn","description":"zhēn：(1)往杯盏里倒饮料～茶。～酒。\n(2)古代指精羹汁厨人进～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斟"},{"id":"glyph-seal-65a1","script":"seal","character":"斡","reading":"wò；guǎn","description":"wò：转，旋～流。～运。～旋（调解，把弄僵了的局面扭转过来）。\nguǎn：古同管”，主管，掌管。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斡"},{"id":"glyph-seal-65a4","script":"seal","character":"斤","reading":"jīn","description":"jīn：(1)中国市制重量单位二～。～～（过分计较琐细的或无关紧要的事物，如～～计较”）。\n(2)古代砍伐树木的工具斧～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斤"},{"id":"glyph-seal-65a7","script":"seal","character":"斧","reading":"fǔ","description":"fǔ：(1)砍东西用的工具，多用来砍木头。古代亦用来作兵器～子。～头。～钺。～柯（ａ．斧子的柄；ｂ．喻政权、权柄）。\n(2)用斧砍～正（敬辞，请人修正文句，亦作斧政”）。～凿（ａ．斧子或凿子；ｂ．指文艺作品等矫揉造作）。～藻（雕饰、修饰）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斧"},{"id":"glyph-seal-65a9","script":"seal","character":"斩","reading":"zhǎn","description":"失期当斩。\n借第令毋斩。\n斩zhǎn砍，杀～首。～草除根。～钉截铁。～断魔爪。～敌者受赏。\n斩zhàn 1.沾。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斩"},{"id":"glyph-seal-65ab","script":"seal","character":"斫","reading":"zhuó","description":"zhuó：大锄；引申为用刀、斧等砍～伐。～丧（sàng）（喻摧残、伤害，特指因沉溺酒色而伤害身体）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斫"},{"id":"glyph-seal-65ad","script":"seal","character":"断","reading":"duàn","description":"断开;断绝\n切肉肉断而发\n①长形东西从中截开折～、线～了。\n②断绝～水、关系～了。\n④判断；决断诊～、当机立～。\n⑤绝对～无此理。\n【断编残简】见【残篇断简】。\n【断层】岩层的连续性遭到破坏并沿破裂面有明显相对移动的一种断裂构造。根据断层两侧相对移动的性质可分为正断层、逆断层、平移断层等。\n【断层面】两部分岩块作相对移动的断裂面。\n【断层山】地壳断裂运动形成的块状山体。可分为地垒式断层山和掀斜式断层山。前者山坡为断层崖，后者山形不对称，断裂上升一侧为断层崖，另一侧为平缓山坡。又称断块\n山。\n【断层崖】〈地〉断层的上升盘突露地表而形成的悬崖。是由于断层线两边岩石受差别侵蚀形成的。断层崖因受垂直于断层面的流水侵蚀而形成v形谷。\n【断肠】形容极度思念、悲痛或忧伤。\n【断炊】没柴没米不能做饭。形容极为穷困。\n【断简残编】见【残篇断简】。\n【断简残篇】见【残篇断简】。\n【断交】绝交。常用于国际关系中。\n【断句】古书没有标点符号，诵读时根据文义作停顿，或同时在书上按停顿加圈点。这里的'句'与现代的'句'不尽相同。\n【断裂生殖】某些生物身体断裂后，每段均能生活，生长成新的个体，称为断裂生殖。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-断"},{"id":"glyph-seal-65af","script":"seal","character":"斯","reading":"sī","description":"sī：(1)这，这个，这里～人。～时。以至于～。\n(2)乃，就有备～可以无患。\n(3)劈墓门有棘，斧以～之”。\n(4)古同厮”，卑贱。\n(5)古同澌”，尽。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斯"},{"id":"glyph-seal-65b0","script":"seal","character":"新","reading":"xīn","description":"xīn：(1)刚有的，刚经验到的；初始的，没有用过的，与旧”、老”相对～生。～鲜。～奇。～贵。～绿。～星。～秀。～闻。～陈代谢。\n(2)性质改变得更好，与旧”相对改过自～。推陈出～。\n(3)不久以前，刚才～近。\n(4)表示一种有异于旧质的状态和性质～时代。～社会。～观念。～思维。\n(5)称结婚时的人或物～娘。～郎。～房。\n(6)中国新疆维吾尔自治区的简称。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-新"},{"id":"glyph-seal-65b9","script":"seal","character":"方","reading":"fāng","description":"fāng：(1)四个角都是90暗乃谋咝位蛄个面都是直角四边形的立体～材（亦称方子”）。～舟?(2)\n数学上指某数自乘的积～根。平～。开～。\n(3)人的品行端正～正。～直。\n(4)一边或一面～向。～面。\n(5)地区，地域地～。～志。～言。～物。～圆。～隅（边疆）。～舆（指领域，亦指大地）。\n(6)办法，做法，技巧～式。～法。教导有～。贻笑大～。\n(7)种，类变幻无～。仪态万～。\n(8)为治疗某种疾病而组合起来的若干种药物的名称、剂量和用法药～。\n(9)违背～命。\n(10)正在，正当～今盛世。～兴未艾。\n(11)才，刚刚～才。如梦～醒。\n(12)量词，多指一立方米土石～。\n(13)量词，用于方形的东西几～石章。\n(14)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-方"},{"id":"glyph-seal-65bd","script":"seal","character":"施","reading":"shī","description":"shī：(1)实行～工。～政。设～。～展。～教（jiào）。～为（wéi）。～威。实～。措～（办法）。发号～令。\n(2)用上，加工～肥。～粉。\n(3)给予～礼。～诊。～恩。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-施"},{"id":"glyph-seal-65c1","script":"seal","character":"旁","reading":"páng；bàng","description":"páng：(1)左右两侧～边。～侧。～门。～出。～听。～若无人。\n(2)其他，另外～人。～的话。触类～通。责无～贷。～证。～白（戏剧角色背着台上其他剧中人对观众说的话）。～落。\n(3)广，广泛～征博引。\n(4)邪、偏～门左道。\n(5)汉字形体中常常出现的某些组成部分偏～。竖心～儿。\nbàng：古同傍”，靠。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旁"},{"id":"glyph-seal-65c3","script":"seal","character":"旃","reading":"zhān","description":"zhān：(1)古代一种赤色曲柄的旗。\n(2)同毡”。\n(3)文言助词，相当于之”或之焉”天其殃之也，其将聚而歼～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旃"},{"id":"glyph-seal-65c4","script":"seal","character":"旄","reading":"máo；mào","description":"máo：古代用牦牛尾装饰的旗子上将拥～西出征，平明吹笛大军行”。\nmào：古同耄”，年老。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旄"},{"id":"glyph-seal-65c5","script":"seal","character":"旅","reading":"lǚ；lv","description":"lǚ：(1)出行的，在外作客的～行（xíng）。～馆。～次。～居。～客。～伴。商～。差（chāi）～。～社。\n(2)军队的编制单位，在师与团之间。\n(3)泛指军队军～。强兵劲～。\n(4)共同～进～退。\n(5)同稆”。\n(6)古同膂”，脊梁骨。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旅"},{"id":"glyph-seal-65c6","script":"seal","character":"旆","reading":"pèi","description":"pèi：(1)古代旗末端状如燕尾的垂旒。\n(2)泛指旌旗。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旆"},{"id":"glyph-seal-65cb","script":"seal","character":"旋","reading":"xuán；xuàn","description":"xuán：(1)转动～绕。～转。～舞。～梯。～律。盘～。天～地转。\n(2)回，归凯～。\n(3)不久～踵（喻极短的时间，如～～即逝”）。～即。\n(4)表示与各方来往或来往于各方之间周～。斡～。\n(5)古同漩”，漩涡。\n(6)姓。\nxuàn：(1)打转的～风。\n(2)临时（做）～吃～做。\n(3)用车床或刀子转着圈地削用车床～零件。把瓜皮～下去。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旋"},{"id":"glyph-seal-65cc","script":"seal","character":"旌","reading":"jīng","description":"jīng：(1)古代用羽毛装饰的旗子。又指普通的旗子～旗。～铭（旧时丧礼，柩前书死者姓名的旗幡）。\n(2)表扬～表。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旌"},{"id":"glyph-seal-65cf","script":"seal","character":"族","reading":"zú","description":"zú：(1)亲属，泛指同姓之亲～规。～长。家～。\n(2)指具有共同起源和共同遗传特征的人群种～。\n(3)指在历史上形成的人群的稳定共同体，他们有共同的语言、经济生活以及表现于共同文化上的心理素质民～。\n(4)聚居而有血统关系的人群的统称宗～。氏～。部～。\n(5)事物有共同属性的一大类芳香～。\n(6)封建时代的一种残酷刑罚，一人有罪，把全家或包括母亲、妻家的人都杀死～灭。\n(7)聚合，集中云气不待～而雨。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-族"},{"id":"glyph-seal-65d6","script":"seal","character":"旖","reading":"yǐ","description":"yǐ：〔～旎〕ａ．旌旗随风飘扬的样子；ｂ．柔和美丽。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旖"},{"id":"glyph-seal-65d7","script":"seal","character":"旗","reading":"qí","description":"qí：(1)用布、纸、绸子或其他材料做成的标识（zhì），多是长方形或方形～子。～帜。～号。～舰。～手。\n(2)中国清代满族的军队编制和户口编制（共分八旗，后又建立蒙古八旗，汉军八旗），特指属于满族的～人（满族人）。～籍。～袍。\n(3)中国内蒙古自治区的行政区划，相当于县。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旗"},{"id":"glyph-seal-65e0","script":"seal","character":"无","reading":"wú","description":"哲学范畴,指无形、无名、虚无等,或指物质的隐微状态\n没有,跟有”相对\n无不变色。\n无不毕肖。\n⒈没有，跟\"有\"相对～粮～钱。～穷～尽。\n⒉不～仿说出。\n⒊不分，不论，不外～分。～论，地～四方。民～异国。事～大小。～非如此。\n⒋通\"毋\"。不，不要～往。\n无mó 1.见\"南无\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-无"},{"id":"glyph-seal-65e2","script":"seal","character":"既","reading":"jì","description":"jì：(1)动作已经完了～往不咎。～而。\n(2)已经～成事实。～定。\n(3)常与且”、又”连用，表示两者并列～快又好。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-既"},{"id":"glyph-seal-65e5","script":"seal","character":"日","reading":"rì","description":"太阳，也指一天。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-seal-65e6","script":"seal","character":"旦","reading":"dàn","description":"dàn：(1)早晨～暮。通宵达～。枕戈待～。\n(2)表示某一天，亦指农历的初一日～望（农历的初一和十五日）。元～。～日（ａ．明天ｂ．白天）。\n(3)传统戏剧里扮演女子的角色老～。花～。\n(4)纤度单位，九千米长的纤维重量为多少克，它的纤度就是多少旦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旦"},{"id":"glyph-seal-65e7","script":"seal","character":"旧","reading":"jiù","description":"鸺鷙,即猫头鹰\n故交,老交情\n原有的典章制度\n指世族\n通丘”。丘冢,坟墓\n越王\n⒈陈的，过时的，跟\"新\"相对～的。～日。守～。～调重弹。〈引〉原来的，从前的～山河。～地重游。～恨新仇。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旧"},{"id":"glyph-seal-65e8","script":"seal","character":"旨","reading":"zhǐ","description":"zhǐ：(1)意义，目的意～。要～。主～。言近～远。\n(2)封建时代称帝王的命令～令。奉～。\n(3)美味～酒。甘～。～蓄（贮藏的美好食品）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旨"},{"id":"glyph-seal-65e9","script":"seal","character":"早","reading":"zǎo","description":"zǎo：(1)太阳出来的时候～晨。～晚。\n(2)时间靠前，有一定的时间以前～退。～恋。～慧（幼时聪明）。～衰。～逝（早死）。\n(3)时间在先的，从前～期。～春。～已。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-早"},{"id":"glyph-seal-65ec","script":"seal","character":"旬","reading":"xún","description":"xún：(1)十日为一旬（一个月分三旬）上～。中～。下～。～刊。\n(2)十岁为一旬年过六～。八～老者。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旬"},{"id":"glyph-seal-65ed","script":"seal","character":"旭","reading":"xù","description":"xù：(1)光明，早晨太阳才出来的样子～日东升。朝（zhāo）～。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旭"},{"id":"glyph-seal-65f0","script":"seal","character":"旰","reading":"gàn；hàn","description":"gàn：晚，天色晚～食宵衣（天晚才吃饭，天未亮就穿衣起床，多用以称谀帝王勤劳政事）。\nhàn：〔～～〕盛大的样子，如皓皓～～，丹彩煌煌”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旰"},{"id":"glyph-seal-65f1","script":"seal","character":"旱","reading":"hàn","description":"hàn：(1)长时间不下雨，缺雨，缺水，与涝”相对～季。～灾。干～。防～。\n(2)非水田的、无水的、陆地上的，与水无关的～井。～田。～獭。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旱"},{"id":"glyph-seal-65f6","script":"seal","character":"时","reading":"shí","description":"⒈一切物质不断运动变化或发展所经历的过程～间。～候。～光。\n⒉时间的一段～期。～代。古～。秦～。平～。瞬～。盛极一～。\n⒊时间单位。一天分子～、丑～、寅～等十二～辰。一天分二十四小～。\n⒋节令，季节～令。～节。春夏秋冬四～。应～服装。\n⒌现在的，当前的～事。～髦。\n⒍经常，常常～常。～ ～见到。\n⒎不经常，间或～而。有～候。～好～坏。\n⒏规定的时间准～。按～上下班。\n⒐不定的时间不～。随～。\n⒑机会，具有时间性的有利条件～机。～不可失。～不再来。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-时"},{"id":"glyph-seal-65f7","script":"seal","character":"旷","reading":"kuàng","description":"心境开阔,开朗\n空旷;开阔\n率彼旷\n⒈广大，空阔～野荒郊。空～无人。土地平～。\n⒊空缺，荒废久～。～课。～工。～日持久。\n⒋历时久远～年。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旷"},{"id":"glyph-seal-65f8","script":"seal","character":"旸","reading":"yáng","description":"日出；晴天，如旸谷、雨旸。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-65fb","script":"seal","character":"旻","reading":"mín","description":"秋天；也泛指天空，如旻天。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-6602","script":"seal","character":"昂","reading":"áng","description":"áng：(1)仰，高抬～首。～然。\n(2)高，贵～贵。价～。\n(3)情绪高～扬。高～。～藏（cáng）（形容人的仪表雄伟，气宇不凡的样子）。～奋。气～～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昂"},{"id":"glyph-seal-6603","script":"seal","character":"昃","reading":"zè","description":"zè：太阳偏西～食宵衣（旧时称颂帝王勤于政事的套话，太阳偏西时才吃饭，天未亮就穿衣）。旰～（天晚，喻勤于政事）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昃"},{"id":"glyph-seal-6606","script":"seal","character":"昆","reading":"kūn","description":"kūn：(1)子孙，后嗣～裔（子孙后代）◇～。\n(2)哥哥～弟（ａ．兄弟；ｂ．友好亲爱）。～仲。～季。～玉（称人兄弟的敬辞）。\n(3)众多～虫（虫类的统称）。\n(4)山名（ａ．昆山”，在中国上海市和江苏省；ｂ．昆仑山”，在中国新疆维吾尔自治区、西藏自治区和青海省交界处，亦作崑??山”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昆"},{"id":"glyph-seal-6609","script":"seal","character":"昉","reading":"fǎng","description":"明亮；开始，如“昉于此”。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-660a","script":"seal","character":"昊","reading":"hào","description":"hào：(1)大（指天）～天（ａ．广大的天；ｂ．喻父母的恩情深重）。～穹。～苍。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昊"},{"id":"glyph-seal-660c","script":"seal","character":"昌","reading":"chāng","description":"chāng：(1)兴盛～盛（shèng）。～乐（lè）（兴盛康乐）。～明（兴盛发达）。～隆。\n(2)善，正当～言（美言，正当的话）。～言无忌（直言无隐）。\n(3)古同菖”，菖蒲。\n(4)古同猖”，凶猛。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昌"},{"id":"glyph-seal-660e","script":"seal","character":"明","reading":"míng","description":"明亮，也有清楚、明白之意。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-seal-660f","script":"seal","character":"昏","reading":"hūn","description":"hūn：(1)天刚黑的时候黄～。～晓（朝夕。亦指明暗）。～定晨省（xǐng）（人子侍奉父母的日常礼节，晚上服侍就寝，早上省视问安）。\n(2)暗而无光～暗。～黑。\n(3)惑乱～愦。～聩。～庸。\n(4)神智不清楚或失去知觉发～。～厥（亦称晕厥”）。～乱。\n(5)古同婚”，婚姻。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昏"},{"id":"glyph-seal-6613","script":"seal","character":"易","reading":"yì","description":"yì：(1)不费力，与难”相对容～。～与（容易对付）。～于。\n(2)和悦平～（ａ．态度谦逊和蔼；ｂ．指语言文字浅显）。\n(3)改变～手。～地。变～。\n(4)交换交～。贸～。\n(5)轻慢贵货～土。\n(6)芟治草木～墓（除治墓地的草木）。～其田畴。\n(7)古书名，《周易》的简称（亦称易经”）。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-易"},{"id":"glyph-seal-6614","script":"seal","character":"昔","reading":"xī","description":"xī：(1)以前，从前～者。～人。往～。今～对比。\n(2)古同夕”，夜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昔"},{"id":"glyph-seal-6615","script":"seal","character":"昕","reading":"xīn","description":"xīn：太阳将要出来的时候。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昕"},{"id":"glyph-seal-6619","script":"seal","character":"昙","reading":"tán","description":"密布的云气\n昙摩。意为法,佛法\n⒈多云，密布的云彩。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昙"},{"id":"glyph-seal-661f","script":"seal","character":"星","reading":"xīng","description":"星辰，夜空中可见的星体。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-seal-6620","script":"seal","character":"映","reading":"yìng","description":"yìng：(1)照射～射。～照。\n(2)反照，照射而显示反～（ａ．反照，反射；ｂ．把容观事物表现出来；ｃ．向上级转达，如～～群众意见”）。～衬（映托使显现）。～雪读书（形容家贫而苦读）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-映"},{"id":"glyph-seal-6625","script":"seal","character":"春","reading":"chūn","description":"一年四季中的春季，草木萌发生长的时节。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-seal-6627","script":"seal","character":"昧","reading":"mèi","description":"mèi：(1)暗，不明幽～。～旦（清晨还未明亮时）。\n(2)昏，糊涂，不明白愚～。蒙～。素～平生（一向不认识）。\n(3)目不明目不别五色之章为～”。\n(4)隐藏，隐瞒暧～。～心（违背良心做坏事）。\n(5)冒犯冒～（多作谦辞）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昧"},{"id":"glyph-seal-6628","script":"seal","character":"昨","reading":"zuó","description":"zuó：今天的前一天，亦泛指过去～天。觉今是而～非（感到现在这样是对的，过去是错误的）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昨"},{"id":"glyph-seal-662d","script":"seal","character":"昭","reading":"zhāo","description":"zhāo：(1)光明～明。～～（ａ．明亮的样子，如日月～～”；ｂ．明白事理。如贤者以其～～，使人～～”）。\n(2)明显，显著～著。～彰。～布。～雪（揭明真情，洗清冤枉）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昭"},{"id":"glyph-seal-662f","script":"seal","character":"是","reading":"shì","description":"shì：(1)表示解释或分类他～工人。《阿Ｑ正传》的作者～鲁迅。\n(2)表示存在满身～汗。\n(3)表示承认所说的，再转入正意，含有虽然”的意思诗～好诗，就是太长了。\n(4)表示适合来的～时候。\n(5)表示任何凡～。～活儿他都肯干。\n(6)用于问句他～走了吗？\n(7)加重语气，有的确”、实在”的意思天气～冷。\n(8)对，合理，与非”相对～非。他说的～。实事求～。\n(9)认为对～古非今。各行其～。深～其言。\n(10)表示应承或同意（单说一个是”字）～，我就去。\n(11)这，此～日。～可忍，孰不可忍。比比皆～。\n(12)助词，把行为对象提前表示只这样做惟你～问。惟利～图。\n(13)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-是"},{"id":"glyph-seal-6631","script":"seal","character":"昱","reading":"yù","description":"yù：(1)日光，光明～～（明亮的样子，亦作煜煜”）。\n(2)照耀日以～乎昼，月以～乎夜”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昱"},{"id":"glyph-seal-6634","script":"seal","character":"昴","reading":"mǎo","description":"mǎo：星名，二十八宿之一。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昴"},{"id":"glyph-seal-6635","script":"seal","character":"昵","reading":"nì","description":"nì：亲近～爱。亲～。～比（亲近勾结）。～称（表示亲近的称呼）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昵"},{"id":"glyph-seal-6636","script":"seal","character":"昶","reading":"chǎng","description":"chǎng：(1)白天时间长。\n(2)舒畅，畅通。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昶"},{"id":"glyph-seal-663c","script":"seal","character":"昼","reading":"zhòu","description":"中午、正午","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昼"},{"id":"glyph-seal-663e","script":"seal","character":"显","reading":"xiǎn","description":"表面,外面\n明显;显示得很清楚\n⒈露在外面，易于看出～露。～明。～著。～然。～而易见。\n⒉表现～示。～现。大～身手。\n⒊有声望、有地位的，旧称有权有势的～扬。～达。～赫。～贵。～宦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-显"},{"id":"glyph-seal-6641","script":"seal","character":"晁","reading":"cháo","description":"cháo：姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晁"},{"id":"glyph-seal-6643","script":"seal","character":"晃","reading":"huàng；huǎng","description":"huǎng：(1)明亮明～～。\n(2)照耀～眼。\n(3)形影很快地闪过一～十年。\n摆；摇；\nhuàng：摇动～荡。～动。～悠。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晃"},{"id":"glyph-seal-664b","script":"seal","character":"晋","reading":"jìn","description":"jìn：(1)进～级。～升。～谒（进见）。\n(2)中国周代诸侯国名。\n(3)中国山西省的别称～剧。\n(4)中国朝代名西～。东～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晋"},{"id":"glyph-seal-664f","script":"seal","character":"晏","reading":"yàn","description":"yàn：(1)迟，晚～起。～驾。\n(2)天清无云天清日～。\n(3)鲜艳。\n(4)同宴”③。\n(5)安定，安乐～宁～处（chù）（安然处之）。～安。～然。\n(6)姓。\n〔～～〕温柔，和悦，如言笑～～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晏"},{"id":"glyph-seal-6652","script":"seal","character":"晒","reading":"shai","description":"暴晒;晒干","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晒"},{"id":"glyph-seal-6653","script":"seal","character":"晓","reading":"xiǎo","description":"清晨\n晓光浮\n⒈天亮拂～。天～。\n⒉知道，明白～得。家喻户～。\n⒊告知～以利弊。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晓"},{"id":"glyph-seal-6655","script":"seal","character":"晕","reading":"yūn","description":"昏倒\n日月周围的光圈\n环形花纹或波纹\n⒈昏迷～倒。～厥。\n⒈日光或月光通过云层因折射作用而看到日或月周围形成的光圈日～。月～。\n⒉头发昏～车。～船。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晕"},{"id":"glyph-seal-665a","script":"seal","character":"晚","reading":"wǎn","description":"wǎn：(1)太阳落了的时候～景。～霞。～会。～报。\n(2)一个时期的后段，在一定时间以后来～了。～年。～期。～节。～婚。\n(3)后来的～生（旧时文人对前辈的自谦）。～辈。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晚"},{"id":"glyph-seal-665e","script":"seal","character":"晞","reading":"xī","description":"xī：(1)干，干燥～发。晨露未～。\n(2)破晓东方未～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晞"},{"id":"glyph-seal-665f","script":"seal","character":"晟","reading":"shèng；chéng","description":"shèng：(1)光明。\n(2)旺盛，兴盛。\nchéng：姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晟"},{"id":"glyph-seal-6664","script":"seal","character":"晤","reading":"wù","description":"wù：(1)遇，见面～面。～谈。～商。会～。\n(2)古同悟”，明白。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晤"},{"id":"glyph-seal-6666","script":"seal","character":"晦","reading":"huì","description":"huì：(1)农历每月的末一天，朔日的前一天～朔。\n(2)夜晚～明。风雨如～。\n(3)昏暗不明～暝。～暗。～涩（意义隐晦，文字僻拗）。隐～（意义不明显）。\n(4)不顺利，倒霉～气。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晦"},{"id":"glyph-seal-6668","script":"seal","character":"晨","reading":"chén","description":"chén：清早，太阳出来的时候早～。凌～。～光。～曦（晨光）。～风。～雾。～炊。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晨"},{"id":"glyph-seal-666e","script":"seal","character":"普","reading":"pǔ","description":"pǔ：全，广，遍～遍。～通。～查。～照。～天同庆。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-普"},{"id":"glyph-seal-666f","script":"seal","character":"景","reading":"jǐng；yǐng","description":"jǐng：(1)环境的风光～色。～致。～物。～观。～气（ａ．景色；ｂ．指经济繁荣现象，统指兴旺）。～深。\n(2)情况，状况～象。～况。年～。\n(3)佩服，敬慕～仰。～慕。\n(4)高，大～行（xíng）。\n(5)姓。\nyǐng：古同影”，影子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-景"},{"id":"glyph-seal-6676","script":"seal","character":"晶","reading":"jīng","description":"jīng：形容光亮～莹。～亮。～明。亮～～。\n〔结～〕ａ．物质从液态或气态形成晶体；ｂ．喻珍贵的成果，如这部作品是他多年研究的～～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晶"},{"id":"glyph-seal-6677","script":"seal","character":"晷","reading":"guǐ","description":"guǐ：(1)日影。\n(2)时间日无暇～。\n〔日～〕按照日影测定时刻的仪器。亦称日规”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晷"},{"id":"glyph-seal-667a","script":"seal","character":"智","reading":"zhì","description":"zhì：聪明，见识～力。～慧。～商。～育。～能。～谋。才～。机～。理～。明～（ａ．考虑问题周到、严密；ｂ．有远见）。足～多谋。利令～昏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-智"},{"id":"glyph-seal-6682","script":"seal","character":"暂","reading":"zàn","description":"暂时\n求假暂归。\n刚刚;方才","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-暂"},{"id":"glyph-seal-6687","script":"seal","character":"暇","reading":"xiá","description":"xiá：空闲，没有事的时候得～。闲～。无～。应接不～。目不～接。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-暇"},{"id":"glyph-seal-6691","script":"seal","character":"暑","reading":"shǔ","description":"shǔ：(1)热～天。～热。～假。酷～。\n(2)中医学六淫”之一。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-暑"},{"id":"glyph-seal-6697","script":"seal","character":"暗","reading":"àn","description":"àn：(1)不亮，没有光，与明”相对黑～。～淡（ａ．不光明；ｂ．喻景象悲惨）。阴～。～无天日。\n(2)不公开的，隐藏不露的～藏。～号。～杀。～娼。～沟。～含（做事、说话包含某种意思而未明白说出）。～流（ａ．流动的地下水；ｂ．喻潜伏的思想倾向或社会动态）。明察～访。\n(3)愚昧，糊涂～昧。～弱（愚昧软弱）。兼听则明，偏信则～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-暗"},{"id":"glyph-seal-66a8","script":"seal","character":"暨","reading":"jì","description":"jì：(1)和，及，与。\n(2)到，至～今。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-暨"},{"id":"glyph-seal-66b4","script":"seal","character":"暴","reading":"bào；pù","description":"bào：(1)强大而突然来的，又猛又急的～雷。～病。～动。～力。～涨。～发。风～。～风骤雨（亦喻声势浩大、发展迅猛的群众运动）。\n(2)过分急躁的，容易冲击的脾气～躁。～跳如雷。\n(3)凶恶残酷的凶～。～虐。～君。～戾恣睢（残暴凶狠，任意胡为）。～政♂征～敛。\n(4)横蹋，损害自～自弃。～殄天物（任意糟蹋东西）。\n(5)鼓起来，突出～起青筋。\n(6)徒手搏击～虎冯（pīng）河（喻有勇无谋）。\n(7)姓。\n〔～露〕显露，如～～无遗”。\npù：同曝1”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-暴"},{"id":"glyph-seal-66d9","script":"seal","character":"曙","reading":"shǔ","description":"shǔ：天刚亮～色。～光（破晓之光，喻已经在望的美好前景）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-曙"},{"id":"glyph-seal-66dc","script":"seal","character":"曜","reading":"yào","description":"yào：(1)照耀；明亮日出有～”。\n(2)日、月、星均称曜”，日、月、火、水、木、金、土七个星合称七曜”，旧时分别用来称一个星期的七天，如日曜日”是星期日，月曜日”是星期一，其余依次类推。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-曜"},{"id":"glyph-seal-66e9","script":"seal","character":"曩","reading":"nǎng","description":"nǎng：以往，从前，过去的～日。～年。～时。～者（从前）。～昔。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-曩"},{"id":"glyph-seal-66f0","script":"seal","character":"曰","reading":"yuē","description":"yuē：(1)说子～诗云。\n(2)为（wéi），是一～水，二～火，三～木，四～金，五～土。\n(3)叫做凡乐辞～诗，诗声～歌。\n(4)语助词，无实义昊天～明。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-曰"},{"id":"glyph-seal-66f2","script":"seal","character":"曲","reading":"qǔ","description":"qǔ：(1)能唱的文词，一种艺术形式～艺。～话。\n(2)歌的乐调～调（diào）。～谱。异～同工。～高和（hè）寡。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-曲"},{"id":"glyph-seal-66f3","script":"seal","character":"曳","reading":"yè","description":"yè：拉，牵引～引。～扯。弃甲～兵。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-曳"},{"id":"glyph-seal-66f4","script":"seal","character":"更","reading":"gèng；gēng","description":"gēng：(1)改变，改换～正。～生（重新获得生命，喻复兴）。～衣（ａ．换衣服；ｂ．婉辞，上厕所）。～定（改订）。～迭（轮流更换）。～递。～番。～新（旧的除去，新的建起）。～张（调节琴弦，喻变更或改革）。\n(2)经历少（shào）不～事（年龄小，没有经历过多少事情）。\n(3)旧时夜间计时单位，一夜分为五更～时。～阑。～夫。～鼓。～漏（原指计时用的漏壶，后泛指时辰）。\ngèng：愈加，再～加。～好。～上一层楼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-更"},{"id":"glyph-seal-66f7","script":"seal","character":"曷","reading":"hé","description":"hé：(1)何，什么蹈死不顾，亦～故哉？”\n(2)怎么，为什么汝～弗告朕？”\n(3)古同盍”，何不。\n(4)何时悠悠苍天，～其有所？”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-曷"},{"id":"glyph-seal-66f9","script":"seal","character":"曹","reading":"cáo","description":"cáo：(1)等，辈尔～（你们）。吾～。\n(2)古代分科办事的官署部～（中国明、清两代各部司曹的通称，源于汉代曹史的简称，相当于郡守的总务长）。\n(3)诉讼的原告、被告两方。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-曹"},{"id":"glyph-seal-66fc","script":"seal","character":"曼","reading":"màn","description":"màn：(1)长，延长～延。～声而歌。\n(2)美，柔美～妙。～靡。～辞。轻歌～舞。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-曼"},{"id":"glyph-seal-66fe","script":"seal","character":"曾","reading":"céng；zēng","description":"zēng：(1)指与自己中间隔两代的亲属～祖父。～孙。\n(2)古同增”，增加。\n(3)竟，简直，还（hái）以君之力～不能损魁父之丘，如太山、王屋何？”\n(4)姓。\ncéng：(1)尝，表示从前经历过～经。未～∥～。～几何时。\n(2)古同层”，重（chóng）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-曾"},{"id":"glyph-seal-66ff","script":"seal","character":"替","reading":"tì","description":"tì：(1)代，代理代～。更（gēng）～。。～班。～身。～罪羊。\n(2)为，给～他送行。～古人担忧。\n(3)衰废兴（xīng）～。衰～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-替"},{"id":"glyph-seal-6700","script":"seal","character":"最","reading":"zuì","description":"zuì：(1)极，无比的～大。～高。～初。～终。～为（wéi）。\n(2)聚合忧喜～门。\n(3)合计～大将军青凡七出击匈奴”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-最"},{"id":"glyph-seal-6708","script":"seal","character":"月","reading":"yuè","description":"月亮，也指月份。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-seal-6709","script":"seal","character":"有","reading":"yǒu；yòu","description":"yǒu：(1)存在～关。～方（得法）。～案可稽。～备无患。～目共睹。\n(2)表示所属他～一本书。\n(3)表示发生、出现～病。情况～变化。\n(4)表示估量或比较水～一丈多深。\n(5)表示大、多～学问。\n(6)用在某些动词前面表示客气～劳。～请。\n(7)无定指，与某”相近～一天。\n(8)词缀，用在某些朝代名称的前面～夏。～宋一代。\n无；没；\nyòu：古同又”，表示整数之外再加零数。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-有"},{"id":"glyph-seal-670b","script":"seal","character":"朋","reading":"péng","description":"péng：(1)彼此友好的人～友。～辈。～侪。～俦。宾～。至爱亲～。\n(2)结党～党（为私利而互相勾结、排斥异己的一帮人）。\n(3)成群群居～飞。\n(4)古代以贝壳为货币，五贝为一串，两串为一朋。\n(5)比硬大无～。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-朋"},{"id":"glyph-seal-670d","script":"seal","character":"服","reading":"fú；fù","description":"fú：(1)衣裳～装。制～。\n(2)穿衣裳～丧。～用（ａ．指穿衣服、用器物；ｂ．吃药）。\n(3)作，担任～务。～刑。～兵役。\n(4)顺从信～。佩～。降（xiáng）～。～辩（旧指认罪书）。～膺（牢记在胸中，衷心信服）。\n(5)习惯，适应不～水土。\n(6)吃（药）内～。\n(7)乘，用～牛乘（chéng）马。\n(8)姓。\nfù：量词，指中药（亦作付”）两～药。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-服"},{"id":"glyph-seal-6710","script":"seal","character":"朐","reading":"qú；xù；chǔn","description":"qú：(1)屈曲的干肉。\n(2)远。\n(3)古书上说的一种植物。\n(4)古地名。\n(5)姓。\nxù：古同昫”，温暖。\nchǔn：蚯蚓。亦称曲蟮”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-朐"},{"id":"glyph-seal-6714","script":"seal","character":"朔","reading":"shuò","description":"shuò：(1)农历每月初一～日。～望（朔日”和望日”）。\n(2)始皆从其～”。\n(3)北方～方。～漠（北方沙漠地带）。～气。～土。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-朔"},{"id":"glyph-seal-6715","script":"seal","character":"朕","reading":"zhèn","description":"zhèn：(1)我，我的。中国秦始皇时起专用作皇帝自称～为始皇帝”。\n(2)征兆，迹象～兆。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-朕"},{"id":"glyph-seal-6717","script":"seal","character":"朗","reading":"lǎng","description":"lǎng：(1)明亮，光线充足～敞。～澈。～然。明～。晴～。开～。爽～。\n(2)声音清楚、响亮～声。～读。～诵。书声～～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-朗"},{"id":"glyph-seal-671b","script":"seal","character":"望","reading":"wàng","description":"wàng：(1)看，往远处看～见。眺～。张～。～尘莫及（喻远远落后）。～风捕影。\n(2)拜访看～。拜～。探～。\n(3)希图，盼期～。欲～。喜出～外。\n(4)人所敬仰的，有名的～族。名～。声～。威～。\n(5)向，朝着～东走。\n(6)月圆，农历每月十五日前后～日。\n(7)埋怨，责备怨～。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-望"},{"id":"glyph-seal-671d","script":"seal","character":"朝","reading":"cháo；zhāo","description":"cháo：朝向；朝见；朝廷、朝代。zhāo：早晨，如朝阳、朝夕。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-671f","script":"seal","character":"期","reading":"qī；jī","description":"qī：(1)规定的时间，或一段时间定～。限～。～限。学～。\n(2)量词，用于刊物或其他分期的事物第五～。\n(3)盼望，希望～望。～冀。～盼。～待。\n(4)限度征敛无～求索无度”。\n(5)必，决定～死，非勇也”。\n(6)地质学上指在一个国境内或一个大区域内，小于世”的地质年代单位。\n〔～颐〕指人活到一百岁。\njī：一周年，一整月～年。～月。～服（古代丧服名，要穿一年）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-期"},{"id":"glyph-seal-6726","script":"seal","character":"朦","reading":"méng","description":"méng：〔～胧〕ａ．月光不明；ｂ．不清楚，凝。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-朦"},{"id":"glyph-seal-6728","script":"seal","character":"木","reading":"mù","description":"mù：(1)树类植物的通称树～。乔～。灌～。～石（树木和石头，喻没有知觉和情感的东西）。缘～求鱼。\n(2)木料、木制品～材。～器。～刻。～匠。～已成舟。\n(3)棺材棺～。\n(4)质朴～讷（朴实迟钝）。\n(5)呆笨～鸡。\n(6)感觉不灵敏，失去知觉麻～。\n(7)中国古代乐器八音之一。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-木"},{"id":"glyph-seal-672a","script":"seal","character":"未","reading":"wèi","description":"wèi：(1)不，不曾，没有～必。～曾（céng）。～来。～尝。～竟（没有完成的）。～及（ａ．没有来得及；ｂ．没有达到）。\n(2)地支的第八位，属羊。\n(3)用于记时～时（下午一点至三点）。\n(4)放在句末，表示疑问君除吏尽～？吾亦欲除吏”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-未"},{"id":"glyph-seal-672b","script":"seal","character":"末","reading":"mò","description":"mò：(1)尖端，梢～梢。～端。秋毫之～（毫毛尖端）。\n(2)最后，终了～了（liǎo）。～尾。～日。～代。穷途～路。\n(3)非根本的，次要的，差一等的～业。～技。舍本逐～。\n(4)碎屑～子。碎～。\n(5)传统戏剧角色名，一般扮演中年以上男子正～。副～。外～。～本（以男角主唱的杂剧）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-末"},{"id":"glyph-seal-672c","script":"seal","character":"本","reading":"běn","description":"běn：(1)草木的根～草（泛指中药）。无～之木。\n(2)事物的根源，与末”相对～末（头尾；始终）。根～（根源；彻底；本质上）。\n(3)草的茎，树的干草～植物。\n(4)中心的，主要的～部。～体。\n(5)原来～来。～领。\n(6)自己这方面的～国。～身。～位。～分（fèn）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-本"},{"id":"glyph-seal-672d","script":"seal","character":"札","reading":"zhá","description":"zhá：(1)古时写字的小木筒～记。\n(2)信件手～。信～。\n(3)旧时的一种公文～子。\n(4)夭死。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-札"},{"id":"glyph-seal-672f","script":"seal","character":"术","reading":"shù；shú；zhú","description":"shù：(1)技艺技～。艺～。武～。学～。不学无～。\n(2)方法战～。权～。心～。\n(3)古代城市中的道路。\nshú：古同秫”，黏高梁。\nzhú：〔白～〕多年生草本植物，根状茎可入药。\n〔苍～〕多年生草本植物，根状茎可入药。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-术"},{"id":"glyph-seal-6731","script":"seal","character":"朱","reading":"zhū；shú","description":"shú：〔～提（shí）〕古地名，在今中国四川宜宾市，产银，故银亦称朱提”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-朱"},{"id":"glyph-seal-6734","script":"seal","character":"朴","reading":"pǔ；pò；pō；piáo","description":"pò：落叶乔木，叶椭圆形，上部边缘有锯齿，花细小，色淡黄，果实球形，黑色，味甜可食。木材可制器具。\npō：〔～刀〕古代的一种武器，窄长有短把的刀，双手使用。\npiáo：姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-朴"},{"id":"glyph-seal-6735","script":"seal","character":"朵","reading":"duǒ","description":"duǒ：(1)植物的花或苞花～。～儿。\n(2)量词，指花或成团的东西三～花。\n(3)动～颐（指动腮颊嚼东西吃的样子）。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-朵"},{"id":"glyph-seal-673a","script":"seal","character":"机","reading":"jī","description":"木名。桤木树\n通几”。几案,小桌子\n⒈〈古〉弓弩上发射箭的机关操弓关～。〈引〉作战设备或其它机械。又特指织布机。\n⒉关键，要点生～。危～。治乱之～。〈引〉\n①保密的或有重要关系的环节～密文件。军～大事。\n②正合适的时候～会。时～。随～应变。～不可失。\n⒊灵巧～灵。～智。～敏。\n⒋机器，由若干零件组成可以做功，或具有特殊作用的装置或设备～床。发电～。电子计算～。\n⒌事情的苗头或预兆～兆。\n⒍事务日理万～。\n①使用机器开动的～动船。\n②随时灵活行动的或准备灵活运用的～动部队。～动处置。～动款。\n①控制整个机器的关键，也指某种有自动装置的器械和设备那里是这部机器的～关。暗设～关。\n②办理事务的机构或单位缩简行政～关。\n③计谋，计策～关算尽太聪明，反误了卿卿性命。\n①机械的内部构造。\n②泛指机关、团体等工作单位，也指它的内部组织精简～构。\n①各种机器、装置、设备的总称化工～械。工业～械。农业～械。\n②呆板，不灵活，工作方式方法固定、老一套没有变化～械的工作。\n机wèi 1.砧板。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-机"},{"id":"glyph-seal-673d","script":"seal","character":"朽","reading":"xiǔ","description":"xiǔ：(1)腐烂腐～。～木。永垂不～（朽”在此引申为磨灭）。\n(2)衰老衰～。～迈。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-朽"},{"id":"glyph-seal-6740","script":"seal","character":"杀","reading":"shā","description":"然得而腊之以为饵,可以已大风、挛踠、瘘、疠,去死肌,杀三虫\n⒈弄死，使失去生命～敌。～猪。～虫剂。\n⒉战斗～退侵略军。～出重围。\n⒊消减，残败～风景。～威风。我花开后百花～。\n⒋收束，断绝～帐。～尾。\n⒌勒紧，扣紧～一～带子。\n⒍药物等刺激身体感到疼痛擦了这种药后～得慌。\n⒎在动词后。〈表〉程度深愁～人。喜～人。\n①凶恶的气势～气腾腾。\n②发泄不愉快的情绪你拿谁～气？\n杀sà 1.散落;散布。 2.古代为护城而设置的防卫据点。 3.枯干貌。\n杀shì 1.古指臣杀君﹑子杀父的行为。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杀"},{"id":"glyph-seal-6742","script":"seal","character":"杂","reading":"zá","description":"混合;搀杂\n聚会;聚集\n驳杂不纯\n⒈不单纯的，各种各样的～事。～色。～粮。～技。人多太～。\n⒉渗入，混合搀～。混～。\n⒊交错长短相～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杂"},{"id":"glyph-seal-6743","script":"seal","character":"权","reading":"quán","description":"秤。测定物体重量的器具\n谨权量、审法度、修废官,四方之政行\n⒈掌握、支配和指挥的力量～力。～柄。～势。政～。职～。\n⒉权利发言～。选举～。\n⒊势力，有利形势制空～。主动～。\n⒋暂且，灵活，变通～且。～宜。～变。\n⒌〈古〉指秤，秤锤铜～。〈引〉衡量 ～衡轻重。\n①最有威望或力量～威人士。\n②在某种范围里最有地位的人或事物学术～威。\n权guàn 1.权火，烽火。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-权"},{"id":"glyph-seal-6748","script":"seal","character":"杈","reading":"chā；chà","description":"chā：一种用来挑柴草等的农具。\nchà：树枝的分岔，树干的分枝～子。打～（除去分枝）。树～儿。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杈"},{"id":"glyph-seal-674e","script":"seal","character":"李","reading":"lǐ","description":"lǐ：(1)落叶小乔木，果实称李子”，熟时呈黄色或紫红色，可食～代桃僵（原用桃”李”共患难来喻兄弟相爱相助，后喻互相顶替或代他人受过）。投桃报～。～下不正冠（喻要避免不必要的嫌疑）。桃～不言，下自成蹊（喻为人只要忠诚、正直一定会感动别人）。\n(2)姓。\n(3)古同理”，古代法官的代称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-李"},{"id":"glyph-seal-674f","script":"seal","character":"杏","reading":"xìng","description":"xìng：落叶乔木，叶卵形，花白色或淡红色，果实称杏儿”、杏子”，酸甜，可食～仁儿。～黄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杏"},{"id":"glyph-seal-6750","script":"seal","character":"材","reading":"cái","description":"cái：(1)木料，泛指一切原料或资料～料。教（jiào）～。素～。题～。就地取～。\n(2)能力，资质～干（gàn）。大～小用。因～施教（jiào）。\n(3)棺木寿～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-材"},{"id":"glyph-seal-6751","script":"seal","character":"村","reading":"cūn","description":"cūn：(1)乡下聚居的处所～子。～塾（旧时农村中的私塾）。～民。\n(2)粗野～野。～俗。～话。～气。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-村"},{"id":"glyph-seal-6753","script":"seal","character":"杓","reading":"sháo；biāo","description":"sháo：同勺”①。\nbiāo：(1)古代指北斗第五、六、七颗星。亦称斗柄”。\n(2)拉开。\n(3)击。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杓"},{"id":"glyph-seal-6756","script":"seal","character":"杖","reading":"zhàng","description":"zhàng：(1)扶着走路的棍子手～。拐～。\n(2)泛指棍棒擀面～。禅～。\n(3)古代刑罚之一，用棍打～脊。\n(4)古同仗”，恃，凭倚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杖"},{"id":"glyph-seal-675c","script":"seal","character":"杜","reading":"dù","description":"dù：(1)落叶乔木，果实圆而小，味涩可食，俗称杜梨”，亦称甘棠”、棠梨”。木材可做扁担或刻图章。\n(2)阻塞（sè），堵塞（sāi）～绝。～塞（sāi）。～门谢客，防微～渐。\n(3)姓～康（相传最早发明酿酒的人，文学作品中借指酒）。\n〔～撰〕凭自己的意思没有根据地编造。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杜"},{"id":"glyph-seal-675e","script":"seal","character":"杞","reading":"qǐ","description":"qǐ：(1)中国周代诸侯国名，在今河南省杞县一带～人忧天（喻不必要的或无根据的忧虑。简称杞忧”）。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杞"},{"id":"glyph-seal-675f","script":"seal","character":"束","reading":"shù","description":"shù：(1)捆住，系～缚。～装（整理行装）。～发（fà）。～之高阁。～手无策。\n(2)量词，用于捆在一起的东西～修（十条干肉，原指学生送给老师的礼物，后指给老师的报酬）。\n(3)聚集成一条的东西光～。电子～。\n(4)控制，限制～身。无拘无～。\n(5)事情的结末收～。结～。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-束"},{"id":"glyph-seal-6760","script":"seal","character":"杠","reading":"gàng；gāng","description":"gàng：(1)一种较粗的棍子～子。～杆。\n(2)在阅读或批改文字中作标记而画的粗直线。\ngāng：(1)旗杆。\n(2)小桥。\n(3)床前横木。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杠"},{"id":"glyph-seal-6761","script":"seal","character":"条","reading":"tiáo","description":"泛指一般长条形的物体\n⒈细长的枝枝～。柳～。荆～子。\n⒉细长的东西铁～。面～。纸～儿。布～子。\n⒊细长的形状～纹。～花布。\n⒋项目，分项目的～目。～款。～例。\n⒌秩序，层次～理。有～有理。\n⒍简短的信便～。字～子。\n⒎凭证借～。收～。\n⒏量词两～鱼。三～大路。四～新闻。\n①影响事物发生、存在或发展的因素客观～件。\n②要求，标准符合～件。\n③状况或基础身体～件。\n④约定或规定的应遵守之事项必须执行所定的～件。\n条tiāo 1.采摘。\n条dí 1.见\"条荡\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-条"},{"id":"glyph-seal-6765","script":"seal","character":"来","reading":"lái","description":"未来,将来\n⒈从甲方到乙方，跟\"去\"、\"往\"相对～电传。～到了天安门广场。\n⒉来到，发生～临。雨～了。～了险情。\n⒌在动词前，〈表〉要做某事我～帮你。大家都～献计献策。\n⒍在动词后，〈表〉趋向，继续做或曾经做过请进～。拿过～。一路走～。这衣服哪儿买～？\n⒎〈表〉粗略估计的数目两米～长。三十～岁。\n⒏助词。在一、二、三等数词后，〈表〉列举获得这一成果的原因一～是领导的关怀支持，二～是同志们的共同努力。\n⒐助词。诗歌里用着衬托，配合音节正月里～是新春。\n⒑［来回］\n①去了再回来。\n②往返一次。\n⒒［来往］\n①来和去。\n②交际。\n⒓［来历］人或事物的由来或经过。\n⒔［来源］事物的起源、根源。\n⒕［来着］助词。用于词尾。〈表〉已发生过的事昨天我们在这儿开会～着。\n来lài 1.慰劳;劝勉。 2.通\"赉\"。送给;赐予。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-来"},{"id":"glyph-seal-6768","script":"seal","character":"杨","reading":"yáng","description":"杨柳科杨属植物的泛称\n⒈比海更大的水域太平～。大西～。\n⒊充满，盛大～溢。\n①水大河水～ ～。〈引〉盛大，众多～ ～万言。\n②美好，高兴得意喜～ ～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杨"},{"id":"glyph-seal-676a","script":"seal","character":"杪","reading":"miǎo","description":"miǎo：(1)树枝的细梢。\n(2)指年月或四季的末尾岁～。月～。秋～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杪"},{"id":"glyph-seal-676d","script":"seal","character":"杭","reading":"háng","description":"háng：(1)中国浙江省杭州市的简称～纺。～剧。\n(2)姓。\n(3)古同航”，渡河。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杭"},{"id":"glyph-seal-6770","script":"seal","character":"杰","reading":"jié","description":"jié：(1)才能出众的人俊～。英雄豪～。\n(2)特异的，超过一般的～作。～出人才。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杰"},{"id":"glyph-seal-6772","script":"seal","character":"杲","reading":"gǎo","description":"gǎo：(1)日出明亮其雨其雨，～～出日。”\n(2)明亮；光明如海之深，如日之～。”\n(3)高远是故民气～乎如登于天，杳乎如入于渊。”\n(4)白。\n(5)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杲"},{"id":"glyph-seal-6773","script":"seal","character":"杳","reading":"yǎo","description":"yǎo：(1)无影无声～无音信。～然无声。～如黄鹤（喻人或物全无踪影）。\n(2)幽暗，深广～渺。～冥。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杳"},{"id":"glyph-seal-6775","script":"seal","character":"杵","reading":"chǔ","description":"chǔ：(1)舂米或捶衣的木棒～臼。砧～。～臼交（旧称互相不嫌贫贱的朋友）。\n(2)用长形的东西戮～了他一拳。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杵"},{"id":"glyph-seal-6777","script":"seal","character":"杷","reading":"pá","description":"pá：〔枇～〕见枇”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杷"},{"id":"glyph-seal-677b","script":"seal","character":"杻","reading":"niǔ；chǒu","description":"niǔ：古书上说的一种树。\nchǒu：古代手铐一类的刑具～械。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杻"},{"id":"glyph-seal-677c","script":"seal","character":"杼","reading":"zhù","description":"zhù：(1)织布机上的筘，古代亦指梭机～（ａ．指织布机，如不闻～～声，惟闻女叹息”；ｂ．喻诗文的构思和布局，如自出～～”）。\n(2)薄，削薄，减削凡为轮，行泽者欲～，行山者欲侔”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杼"},{"id":"glyph-seal-677e","script":"seal","character":"松","reading":"sōng","description":"常绿的针叶树，诗画中常用来象征坚韧。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-seal-6781","script":"seal","character":"极","reading":"jí","description":"最高的地位\n特指君位\n顶点,最高处;最高最\n⒈顶端，最高点，尽头处～端。～点。登峰造～。〈引〉到极点乱～则治。暗～则光。\n⒉最，非常～重。～美好。穷凶～恶。\n⒊竭尽～力工作。～目远望。\n⒋指皇位登～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-极"},{"id":"glyph-seal-6784","script":"seal","character":"构","reading":"gòu","description":"字亦作搆”\n构成,造成\n⒊结怨，幻想，心思～怨。虚～。～思。\n构gōu 1.见\"构栏\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-构"},{"id":"glyph-seal-6787","script":"seal","character":"枇","reading":"pí","description":"pí：〔～杷〕ａ．常绿乔木，叶大，长椭圆形，果实球形，黄色，味甜，叶和核可入药；ｂ．这种植物的果实。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枇"},{"id":"glyph-seal-6789","script":"seal","character":"枉","reading":"wǎng","description":"wǎng：(1)弯曲，弯屈，引申为行为不合正道或违法曲断～道。矫～过正。贪脏～法。～己正人（自己身子不正，倒去矫正别人）。\n(2)冤屈～死。冤～。\n(3)屈就，用于别人，含敬意～驾（ａ．称对方来访自己；ｂ．请对方往访他人）。～顾（称对方来访自己）。～临（称对方来访自己）。\n(4)徒然，空，白～然。～自。～费心机。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枉"},{"id":"glyph-seal-678b","script":"seal","character":"枋","reading":"fāng；bìng","description":"fāng：(1)古书上说的一种树，木材可做车。\n(2)方柱形木材～子（亦指棺材）。\nbìng：古同柄”，权柄。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枋"},{"id":"glyph-seal-6790","script":"seal","character":"析","reading":"xī","description":"xī：(1)分开条分缕～。分崩离～。\n(2)解释分～。剖～。～疑。赏～。～出（ａ．分析出来；ｂ．固体从液体或气体中分离出来）。辨～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-析"},{"id":"glyph-seal-6795","script":"seal","character":"枕","reading":"zhěn","description":"zhěn：(1)躺着时垫在头下的东西～头。落（lào）～。～席。\n(2)躺着的时候，把头放在枕头上或器物上～戈待旦。～藉（纵横相枕而卧）。\n(3)垫着～木（铁路上承受铁轨的横木）。～腕（写字运笔的一种方法，右手垫在左手上写）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枕"},{"id":"glyph-seal-6797","script":"seal","character":"林","reading":"lín","description":"lín：(1)长在一片土地上的许多树木或竹子树～。森～。～海。～薮（ａ．山林小泽；ｂ．喻丛集的处所）。\n(2)聚集在一起的同类的人或事物书～。艺～。碑～。儒～。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-林"},{"id":"glyph-seal-679a","script":"seal","character":"枚","reading":"méi","description":"méi：(1)树干伐其条～。\n(2)古代行军时防止士卒喧哗的用具，状如箸，衔在口中又如赴敌之兵，衔～疾走，不闻号令，但闻人马之行声”。\n(3)马鞭以～数（shǔ）阖（用马鞭指点着数门扇）。\n(4)量词，相当于个”，多用于形体小的东西一～别针。不胜～举（一个一个地举不完）。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枚"},{"id":"glyph-seal-679c","script":"seal","character":"果","reading":"guǒ","description":"guǒ：(1)某些植物花落后含有种子的部分～实。～品。～木。结～（ａ．结出果实；ｂ．事情的结局或成效）。\n(2)结局，与因”相对因～。成～。\n(3)坚决～决。～断。\n(4)确实，真的～真。如～。\n(5)充实，饱足～腹。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-果"},{"id":"glyph-seal-679d","script":"seal","character":"枝","reading":"zhī；qí","description":"zhī：(1)由植物主干上分出来的茎条树～。～干（gàn）。竹～。节外生～。～柯。～节（ａ．由一件事生发的其他问题；ｂ．细碎的，不重要的）。\n(2)量词，指杆形的一～铅笔。\n(3)古同支”，支持，分支。\nqí：古同歧”，岔。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枝"},{"id":"glyph-seal-679e","script":"seal","character":"枞","reading":"cōng","description":"枞树。常绿乔木,又叫冷杉\n枞阳","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枞"},{"id":"glyph-seal-67a2","script":"seal","character":"枢","reading":"shū","description":"木名,即刺榆\n泛指转轴\n半弦弧不满圜半径者,以矢\n⒈门上的转轴户～。\n⒉事物的关键或中心部分～纽。～要。中～神经。\n枢ōu 1.木名。即刺榆。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枢"},{"id":"glyph-seal-67a3","script":"seal","character":"枣","reading":"zǎo","description":"枣树所结的果实","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枣"},{"id":"glyph-seal-67a5","script":"seal","character":"枥","reading":"lì","description":"马房\n古书上指栎树","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枥"},{"id":"glyph-seal-67a8","script":"seal","character":"枨","reading":"chéng","description":"木柱\n古时门两旁所竖的木柱,用以防车过触门。亦称枨臬\n果名。即橙。亦称枨子\n触动,接触而动\n⒈〈古〉竖立在门旁的木柱，用于防车碰门。\n⒉触动～触。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枨"},{"id":"glyph-seal-67aa","script":"seal","character":"枪","reading":"qiāng","description":"古时长柄有尖头的刺击武器\n武器名。火铳,火枪;发射子弹的火器。同鎗”\n⒈长矛长～。铁～§缨～。\n⒉发射弹丸的武器手～。冲锋～。\n⒊武装力量我们的原则是党指挥～，决不容许～指挥党。\n枪chēng 1.星名。参见\"枪星\"﹑\"枪棓\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枪"},{"id":"glyph-seal-67ab","script":"seal","character":"枫","reading":"fēng","description":"落叶乔木,春季开花,黄褐色。叶子掌状三裂,秋季变成红色\n槭属植物俗也称枫\n枫 fēng 枫树，也叫\"香枫\"。落叶乔木。春季开花。叶掌状三裂，秋季变红色。木材供建筑、制家具等用。果实和树脂可供药用。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枫"},{"id":"glyph-seal-67ad","script":"seal","character":"枭","reading":"xiāo","description":"猫头鹰\n旧时指私贩食\n⒈一种凶猛的鸟，已少见，要保护，禁止猎杀。羽毛棕褐色，有横纹。常于夜间飞行，捕食小动物。\n⒉勇猛难制服～将。～雄。\n⒊魁首，头领毒～。匪～。\n⒋旧时悬挂砍下的人头～示。～首。\n⒌山顶山～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枭"},{"id":"glyph-seal-67af","script":"seal","character":"枯","reading":"kū","description":"kū：(1)失去水分，水全没有了干～。～萎。～槁。～荣。～鱼衔索（串在绳索上的干鱼，形容存日不多）。\n(2)没趣味，无生趣～燥。～肠（喻枯涩贫乏的思路）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枯"},{"id":"glyph-seal-67b0","script":"seal","character":"枰","reading":"píng","description":"píng：棋盘棋～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枰"},{"id":"glyph-seal-67b3","script":"seal","character":"枳","reading":"zhǐ；zhī","description":"zhī：落叶灌木或小乔木，小枝多刺，果实黄绿色，味酸不可食，可入药（亦称枸橘”）～实（中药称枳”、构橼”等的近成熟的果实）。～壳（中药称枳”、枸橼”等的成熟的果实）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枳"},{"id":"glyph-seal-67b5","script":"seal","character":"枵","reading":"xiāo","description":"xiāo：(1)空虚～腹。外肥中～。\n(2)布的丝缕稀而薄～薄。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枵"},{"id":"glyph-seal-67b7","script":"seal","character":"枷","reading":"jiā","description":"jiā：旧时一种套在脖子上的刑具～锁（旧时的两种刑具，喻束缚）。～号（古代刑法，将犯人上枷，写明罪状示众）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枷"},{"id":"glyph-seal-67b8","script":"seal","character":"枸","reading":"gǒu；jǔ","description":"jǔ：〔～橼〕ａ．常绿小乔木或大灌木，有短刺。果实长圆形，黄色，有香气，果皮可入药或提制芳香油；ｂ．这种植物的果实。均亦称香橼”。\ngǒu：〔～杞〕落叶小灌木，叶披针形，结小浆果，成熟时红色，称枸杞子”，可入药；根皮称地骨皮”，亦可入药；茎叶嫩时可食。\n〔～骨〕常绿小乔木或灌木，叶长椭圆形有三、四个硬刺，开凶花，有香气，果实球形供观赏，叶入药。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-枸"},{"id":"glyph-seal-67c4","script":"seal","character":"柄","reading":"bǐng","description":"bǐng：(1)植物的花、叶或果实跟枝茎连着的部分叶～。花～。\n(2)器物上的把儿刀～。勺～。\n(3)量词，用于有柄物一～伞。\n(4)喻在言行上被人抓住的材料把（bǎ）～。话～。\n(5)执掌～政（执掌政权）。～国。\n(6)权国～。民～。\n(7)根本谦，德之～也”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柄"},{"id":"glyph-seal-67cf","script":"seal","character":"柏","reading":"bǎi；bó；bò","description":"bǎi：(1)常绿乔木，叶鳞片状，结球果，有扁柏”、侧柏”、圆柏”、罗汉柏”等多种。木质坚硬，纹理致密。可供建筑及制造器物之用～露（柏树上的露水，据说用以洗眼，有明目的作用）。\n(2)姓。\nbó：〔～林〕德国的首都。\nbò：同檗”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柏"},{"id":"glyph-seal-67d0","script":"seal","character":"某","reading":"mǒu","description":"mǒu：(1)代替不明确指出的人、地、事、物等～人。～处。～国。\n(2)自称（代替我”或名字）～姓李。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-某"},{"id":"glyph-seal-67d2","script":"seal","character":"柒","reading":"qī","description":"qī：七”的大写。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柒"},{"id":"glyph-seal-67d3","script":"seal","character":"染","reading":"rǎn","description":"rǎn：(1)把东西放在颜料里使着色～料。～色。～坊。～缸。印～。\n(2)感受疾病或沾上坏习惯或接触到什么～病。感～。传～。沾～。一尘不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-染"},{"id":"glyph-seal-67d4","script":"seal","character":"柔","reading":"róu","description":"róu：(1)植物初生而嫩～荑（初生嫩芽，喻女子白嫩的手）。\n(2)软，不硬～软。～韧。～嫩。～滑。\n(3)软弱，与刚”相对～懦。～弱。刚～相济。\n(4)温和～顺。～和。～曼（柔和妩媚）。～情。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柔"},{"id":"glyph-seal-67d8","script":"seal","character":"柘","reading":"zhè","description":"zhè：(1)落叶灌木或乔木，树皮有长刺，叶卵形，可以喂蚕，皮可以染黄色，木材质坚而致密，是贵重的木料～黄。～蚕。～丝。\n(2)古同蔗”，甘蔗。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柘"},{"id":"glyph-seal-67d9","script":"seal","character":"柙","reading":"xiá","description":"xiá：(1)关闭猛兽的笼槛，亦指押解犯人的囚笼或囚车。\n(2)古同匣”，收藏东西的器具。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柙"},{"id":"glyph-seal-67da","script":"seal","character":"柚","reading":"yòu；yóu","description":"yòu：常绿乔木，果实称柚子，皮粗而厚，色黄，肉白或粉红色，多汁，味酸甜，亦称文旦”。\nyóu：〔～木〕落叶乔木，木材暗褐色，坚硬耐腐蚀，适于制造船舰、车辆等，亦供建筑用。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柚"},{"id":"glyph-seal-67dc","script":"seal","character":"柜","reading":"guì；jǔ","description":"jǔ：〔～柳〕落叶乔木，羽状复叶，小叶长椭圆形，枝韧，可以编筐。性耐湿、耐碱，可固沙，多栽植在路旁做行道树。亦称元宝枫”、杞柳”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柜"},{"id":"glyph-seal-67dd","script":"seal","character":"柝","reading":"tuò","description":"tuò：(1)古代打更用的梆子朔气传金～”。\n(2)古同拓”，开拓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柝"},{"id":"glyph-seal-67de","script":"seal","character":"柞","reading":"zhà；zuò","description":"zuò：栎”的通称～蚕。～丝。～栎。\nzhà：〔～水〕地名，在中国陕西省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柞"},{"id":"glyph-seal-67e0","script":"seal","character":"柠","reading":"níng","description":"木名\n柠檬","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柠"},{"id":"glyph-seal-67e2","script":"seal","character":"柢","reading":"dǐ","description":"dǐ：树木的根；引申为基础根深～固。他的英文很有根～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柢"},{"id":"glyph-seal-67e9","script":"seal","character":"柩","reading":"jiù","description":"jiù：装着尸体的棺材灵～。棺～。～车。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柩"},{"id":"glyph-seal-67ec","script":"seal","character":"柬","reading":"jiǎn","description":"jiǎn：(1)信件、名片、帖子等的泛称请～。书～。\n(2)简选，拣～寄（盐并委托职务）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柬"},{"id":"glyph-seal-67ef","script":"seal","character":"柯","reading":"kē","description":"kē：(1)斧子的柄斧～。\n(2)草木的枝茎交～错叶。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柯"},{"id":"glyph-seal-67f0","script":"seal","character":"柰","reading":"nai；nài","description":"nài：(1)苹果的一种，通称柰子”；亦称花红”、沙果”。\n(2)古同奈”，怎样，如何。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柰"},{"id":"glyph-seal-67f1","script":"seal","character":"柱","reading":"zhù","description":"zhù：(1)建筑物中直立的起支撑作用的构件～子。～石。顶梁～。\n(2)形状像柱子的东西，或作用重要如柱子的水～。～臣（对国家有重要作用的臣子）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柱"},{"id":"glyph-seal-67f3","script":"seal","character":"柳","reading":"liǔ","description":"liǔ：(1)落叶乔木或灌木，枝柔韧，叶狭长，春天开黄绿色花，种子上有白色毛状物，成熟后随风飞散，种类很多，有垂柳”、河柳”、杞柳”等～条。～絮。～暗花明。\n(2)星名，二十八宿之一。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柳"},{"id":"glyph-seal-67f4","script":"seal","character":"柴","reading":"chái","description":"chái：(1)烧火用的草木～草。～火。～门。火～。木～。\n(2)烧柴祭天～于上帝”。\n(3)瘦，不松软～鸡。～心儿。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柴"},{"id":"glyph-seal-67fd","script":"seal","character":"柽","reading":"chēng","description":"木名∮柳,即柽柳\n叫三春柳或红柳\n古地名","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柽"},{"id":"glyph-seal-67ff","script":"seal","character":"柿","reading":"shì","description":"shì：落叶乔木，果实为扁圆形或圆椎形浆果，黄或橙红色，可食～子。～饼。～霜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-柿"},{"id":"glyph-seal-6800","script":"seal","character":"栀","reading":"zhī","description":"zhī：〔～子〕ａ．常绿灌木或小乔木，夏季开白花，有浓香。果实卵形，可入药，亦可作黄色染料。有的地区亦称水横枝”；ｂ．这种植物的果实。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栀"},{"id":"glyph-seal-6805","script":"seal","character":"栅","reading":"shān；zhà；shi；cè","description":"zhà：用竹木铁条等做成的阻拦物～栏。～子。\nshān：〔～极〕多极电子管靠阴极的一个电极。\n〔光～〕产生光的衍射图像的光学仪器。\nshi：〔大～栏〕方言，中国北京市前门外一条热闹街市名。\ncè：〔上～〕\n〔下～〕地名，均在中国广东省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栅"},{"id":"glyph-seal-6807","script":"seal","character":"标","reading":"biāo","description":"末梢;事物的枝节或表面。与本”相对\n顶端\n柱竿之类","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-标"},{"id":"glyph-seal-6808","script":"seal","character":"栈","reading":"zhàn","description":"古代用竹木条横排编成车箱的轻便车子\n车乘栈车\n⒈关养牲畜的棚或栅栏羊～。\n⒉存放货物或供旅客住宿的地方货～。客～。\n⒊〈古〉在险峻绝壁的山上用竹木等架设的道路～道。\n⒋〈古〉竹木做成的车～车。\n栈zhǎn 1.古代乐器。小钟。\n栈chén 1.见\"栈栈\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栈"},{"id":"glyph-seal-6809","script":"seal","character":"栉","reading":"zhì","description":"用梳子梳头发","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栉"},{"id":"glyph-seal-680a","script":"seal","character":"栊","reading":"lóng","description":"窗框格;分隔并支撑窗玻璃的细木条\n⒈窗户窗～。\n⒉养禽兽的栅栏～槛。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栊"},{"id":"glyph-seal-680b","script":"seal","character":"栋","reading":"dòng","description":"②量词。多用于房屋两～楼。\n【栋梁之材】比喻担负国家重任的人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栋"},{"id":"glyph-seal-680c","script":"seal","character":"栌","reading":"lú","description":"柱头承托栋梁的短木。即欂栌、斗栱\n黄栌\n⒈柱顶上承托栋梁的方木，即\"斗拱\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栌"},{"id":"glyph-seal-680e","script":"seal","character":"栎","reading":"lì","description":"即麻栎”。通称柞树”\n一种落叶乔木,花黄褐色,果实叫橡子或橡斗。木材坚硬,可制家具,供建筑。树皮可鞣皮或做染料。叶子可喂柞蚕。另有一种栓皮栎,树皮质地轻软,富有弹性,是制造软木的主要\n原料\n栏杆之类\n⒈俗称\"柞树\"或\"麻栎\"。落叶乔木，花黄褐色。果实叫\"橡子\"或\"橡斗\"，可供药用。叶可喂柞蚕。木材可供建筑、做枕木、制家具等用。还有一种\"栓皮栎\"，树皮质地轻而柔\n软，富有弹性，是制造软木器具的主要原料。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栎"},{"id":"glyph-seal-680f","script":"seal","character":"栏","reading":"lán","description":"饲养家畜的圈\n报纸或刊物中有固定标题或特写的部分\n一面墙壁或特制的告示牌,用以张贴通知、证\n⒈遮挡的东西竹～。铁～。花编～。\n⒉家畜的圈猪～。\n栏liàn 1.木名。即楝。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栏"},{"id":"glyph-seal-6811","script":"seal","character":"树","reading":"shù","description":"种植\n⒈木本植物的总称～木。六棵大～。松～。柏～。植～造林。\n⒉种植，栽培，培养～植草木。十年～木，百年～人。\n⒊竖立，建立～立。～雄心。～新风。独～一帜。\n⒋量词。株，棵种甘桔千～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-树"},{"id":"glyph-seal-6816","script":"seal","character":"栖","reading":"qī；xī","description":"qī：(1)鸟禽歇宿夫以鸟养养鸟者，宜～之深林”。\n(2)居留，停留～身。～息。～止。～遁（隐居，遁世）。～迟（游息，居住）。\nxī：〔～～〕形容不安定。\n〔～遑〕ａ．忙碌不安，到处奔波；ｂ．被迫。均亦作栖皇”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栖"},{"id":"glyph-seal-6817","script":"seal","character":"栗","reading":"lì","description":"lì：(1)落叶乔木，果实为坚果，称栗子”，味甜，可食～色。火中取～。\n(2)发抖，因害怕或寒冷肢体颤动战～。\n(3)坚实缜密以～”。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栗"},{"id":"glyph-seal-681d","script":"seal","character":"栝","reading":"guā；tiǎn","description":"guā：(1)古书上指桧树。\n(2)箭末扣弦处箭～。矢～。\n(3)多年生草本植物，爬蔓，果实椭圆形。根和果实均可入药。通称栝楼”。\ntiǎn：拨火棍。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栝"},{"id":"glyph-seal-681f","script":"seal","character":"栟","reading":"bīng；bēn","description":"bēn：〔～茶〕地名，在中国江苏省。\nbīng：〔～榈〕古书上指棕榈”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栟"},{"id":"glyph-seal-6821","script":"seal","character":"校","reading":"xiào；jiào","description":"xiào：(1)学堂，专门进行教育的机构～园。～长。\n(2)军衔的一级，在将”之下，尉”之上。\n(3)古代军队编制单位～尉（统带一校的军官）。\njiào：(1)比较～场。\n(2)查对、订正～勘。～订。～对。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-校"},{"id":"glyph-seal-6829","script":"seal","character":"栩","reading":"xǔ","description":"xǔ：〔～～〕形容生动传神的样子，如～～如生”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栩"},{"id":"glyph-seal-682a","script":"seal","character":"株","reading":"zhū","description":"zhū：(1)露出地面的树根守～待兔。～连。～戮。\n(2)棵儿，指整个的植物体植～。\n(3)量词，指植物一～桃树。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-株"},{"id":"glyph-seal-6837","script":"seal","character":"样","reading":"yàng","description":"假借为像”。式样\n形状,模样\n⒈形状～子。模～儿。走了～。\n⒉种类这两～。那几～。一个～儿。～ ～都行。\n⒊作为标准或代表的榜～。～板。～品儿。货～子。\n样xiàng 1.橡实。即栎实。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-样"},{"id":"glyph-seal-6838","script":"seal","character":"核","reading":"hé；hú","description":"hé：(1)果实中坚硬并包含果仁的部分桃～。杏～。\n(2)像核的东西～细胞。～酸。～心（中心）。结～。原子～。～子。～反应。～武器。\n(3)仔细地对照、考察～定。～计。～实。～算。～查。\n(4)翔实正确其文直，其事～。\nhú：义同（一）①②，用于某些口语词，如杏核儿”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-核"},{"id":"glyph-seal-6839","script":"seal","character":"根","reading":"gēn","description":"gēn：(1)高等植物茎干下部长在土里的部分～植。～茎。～瘤。～毛。～雕。须～。块～。扎～。叶落归～。\n(2)物体的基部和其他东西连着的部分～底。～基。墙～儿。\n(3)事物的本源～源。～由。～本。知～知底。\n(4)彻底～除。～究。～治。\n(5)依据，作为根本～椐。\n(6)量词，指长条的东西两～筷子。\n(7)数学上称一数开平方所得的值为平方根”，开立方所得的值为立方根”。\n(8)数学上指代数方程式内未知数的值。\n(9)化学上指带电的基氨～。硫酸～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-根"},{"id":"glyph-seal-683c","script":"seal","character":"格","reading":"gé","description":"gé：(1)划分成的空栏和框子～子纸。方～儿布。\n(2)法式，标准～局。～律。～式。～言∠～。资～。\n(3)表现出来的品质～调。风～。人～。国～。性～。\n(4)阻碍，隔阂～～不入。\n(5)击，打～斗。～杀。\n(6)推究～致。\n(7)树的长枝。\n(8)至，来～于上下。\n(9)感通～于皇天。\n(10)变革，纠正～非。\n(11)某些语言中的语法范畴。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-格"},{"id":"glyph-seal-683d","script":"seal","character":"栽","reading":"zāi","description":"zāi：(1)移植～树。～植。～花。～培。\n(2)安上，插上～绒。～赃。\n(3)秧子，可以移植的植物的幼苗桃～。树～子。\n(4)跌倒～跟头。\n(5)指失败或出丑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栽"},{"id":"glyph-seal-683e","script":"seal","character":"栾","reading":"luán","description":"木名。也叫栾华”、灯笼树”\n胶。花可提黄色染料,又可入药\n拱,建筑物立柱和横梁之间成弓形的承重结构\n通孪”。双生子","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-栾"},{"id":"glyph-seal-6840","script":"seal","character":"桀","reading":"jié","description":"jié：(1)凶暴～鹜不驯。～黠。\n(2)古同杰”，杰出的人。\n(3)古同揭”，举起。\n(4)中国夏朝末代君主，相传是暴君～纣。～犬吠尧。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桀"},{"id":"glyph-seal-6842","script":"seal","character":"桂","reading":"guì","description":"guì：(1)中国广西壮族自治区的别称～剧。～系军阀。\n(2)姓。\n〔～花〕常绿小乔木或灌木，叶椭圆形，开白色或暗黄色小花，有特殊的香气，供观赏，亦可做香料，通称木犀”；简称桂”，如金～”，～子飘香”、～轮”（月的别称，相传月中植桂花。亦称桂魄”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桂"},{"id":"glyph-seal-6843","script":"seal","character":"桃","reading":"táo","description":"táo：(1)落叶小乔木，品种很多，果实略呈球形，表面有短绒毛，味甜，有大核，核仁可入药～儿。～李（喻所教的学生）。～李不言，下自成蹊（喻实至名归，尚事实，不尚虚名）。世外～源（指不受外界影响的地方或幻想中的美好世界）。\n(2)形状像桃子的棉～儿。\n(3)指核桃～仁。～酥。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桃"},{"id":"glyph-seal-6845","script":"seal","character":"桅","reading":"wéi","description":"wéi：竖立于船的甲板上的长杆，用来挂帆悬旗或兼做吊杆柱等～杆。～樯（桅杆）。船～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桅"},{"id":"glyph-seal-6848","script":"seal","character":"案","reading":"àn","description":"àn：(1)长形的桌子或架起来代替桌子用的长木板～子。～板。书～。条～。拍～而起。\n(2)提出计划、方法和建议的文件或记录档～。备～。议～。提～。方～。有～可查。～卷。～牍。\n(3)事件，特指涉及法律问题的事件惨～。血～。～件。～例。～犯。破～。\n(4)古代有短脚盛食物的木托盘举～齐眉（形容夫妻相敬）。\n(5)同按”⑤　　。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-案"},{"id":"glyph-seal-684e","script":"seal","character":"桎","reading":"zhì","description":"zhì：(1)古代拘束犯人两脚的刑具～梏。～槛。\n(2)窒，碍，拘束。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桎"},{"id":"glyph-seal-6850","script":"seal","character":"桐","reading":"tóng","description":"tóng：〔泡（pāo）～〕落叶乔木，叶大，开白色或紫色花，木材可做琴、船、箱等物。\n〔梧～〕见梧”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桐"},{"id":"glyph-seal-6851","script":"seal","character":"桑","reading":"sāng","description":"sāng：(1)落叶灌木，叶子可以喂蚕，果穗味甜可食，木材可制家具或农具，皮可造纸，叶、果均可入药。中国大部分地区都有种植～葚。～农。～梓（喻乡里，故乡）。沧海～田（形容世事变迁很大）。～榆暮景。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桑"},{"id":"glyph-seal-6853","script":"seal","character":"桓","reading":"huán","description":"huán：(1)古代立在城郭、宫殿、官署、陵墓或驿站路边的木柱～表。\n(2)大～治（大治）。\n(3)姓。\n〔～～〕威武的样子，如～～陈将军，仗钺奋忠烈”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桓"},{"id":"glyph-seal-6854","script":"seal","character":"桔","reading":"jú；jié","description":"jié：〔～梗〕多年生草本植物，叶卵形或卵状披针形，花暗蓝色或紫色，供观赏。根可入药。\njú：橘”俗作桔”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桔"},{"id":"glyph-seal-6861","script":"seal","character":"桡","reading":"ráo","description":"曲木;木头弯曲;泛指弯曲\n扰动;搅乱\n屈服\n屈弱,削弱\n柔弱长艳\n⒉划船的桨。\n桡náo 1.弯曲。 2.谓使弯曲。 3.屈从;屈服。 4.枉屈。 5.扰动;搅乱。 6.干预;冒犯。 7.削弱。 8.顾望。古代军法术浯。 9.见\"桡桃\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桡"},{"id":"glyph-seal-6862","script":"seal","character":"桢","reading":"zhēn","description":"古代筑墙时竖立在两端的木柱\n支柱,主干\n⒈〈古〉指一种质地坚硬的树。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桢"},{"id":"glyph-seal-6865","script":"seal","character":"桥","reading":"qiáo","description":"器物上的横杆\n木名\n架桥,修桥\n桥jiāo 1.桔槔。井上汲水工具。或指桔槔上的衡木。 2.通\"憍\"。骄傲。参见\"桥泄\"。\n通\"矫\"。矫正。 3.通\"矫\"。伪，虚假。参见\"桥言\"。 4.通\"挢\"。翘起;伸出。 5.劲疾。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桥"},{"id":"glyph-seal-6867","script":"seal","character":"桧","reading":"guì；hui","description":"即圆柏\n⒈桧树，也叫\"桧柏\"、\"圆柏\"。常绿乔木，叶有针状或鳞片两种，果实球形。木质桃红色，坚实，有香味，可供建筑及制造器具、铅笔杆等。\n⒉见huì㈥。\n⒈秦桧，人名。南宋奸臣。\n⒉见guì。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桧"},{"id":"glyph-seal-6869","script":"seal","character":"桩","reading":"zhuāng","description":"储物备用的内库\n旧时赌博头家称坐庄”或称做桩”\n多指事情的件数。如一桩大冤案\n储备;储存\n除刘宝私财还宝外,余并桩充军须。╠\n⒈一端插入地里的木柱或石柱木～。桥～子。拴马～。\n⒉量词。指事情的件数那～事。几～案件。一～一～的弄清楚。\n桩chōng 1.撞击。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桩"},{"id":"glyph-seal-6874","script":"seal","character":"桴","reading":"fú","description":"fú：(1)房屋的次栋，即二栋。\n(2)击鼓的槌～鼓相应。\n(3)小竹筏或小木筏。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桴"},{"id":"glyph-seal-6876","script":"seal","character":"桶","reading":"tǒng","description":"tǒng：(1)盛水或其他东西的器具，深度较大，用金属、木材或塑料等制成水～。饭～。马～。塑料～。\n(2)形状像桶的皮～（做皮衣用的成件的毛皮）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桶"},{"id":"glyph-seal-6877","script":"seal","character":"桷","reading":"jué","description":"jué：(1)方形的椽子。\n(2)指平直如桷的树枝。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-桷"},{"id":"glyph-seal-6881","script":"seal","character":"梁","reading":"liáng","description":"liáng：(1)架在墙上或柱子上支撑房顶的横木，泛指水平方向的长条形承重构件房～。栋～。～上君子（指窃贼）。\n(2)桥桥～。津～（渡口和桥梁，借指学习的门径）。\n(3)器物、身体或其他物体上中间高起的部分鼻～。山～。车～。\n(4)中国战国时期国名，魏国于公元前361年迁都大梁（今河南省开封市）后，改称梁”。\n(5)中国朝代名（ａ．南朝之一；ｂ．五代之一）。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梁"},{"id":"glyph-seal-6883","script":"seal","character":"梃","reading":"tǐng；tìng","description":"tǐng：棍棒。\ntìng：(1)杀猪后，在猪腿上划一个口子，用铁棍贴着腿皮往里捅，然后往里吹气，使猪皮绷紧，以便去毛～猪。\n(2)梃猪时用的铁棍。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梃"},{"id":"glyph-seal-6885","script":"seal","character":"梅","reading":"méi","description":"méi：(1)落叶乔木，品种很多，性耐寒，初春开花，有白、红等颜色，分五瓣，香味很浓，果实球形，味酸～花。～子。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梅"},{"id":"glyph-seal-688f","script":"seal","character":"梏","reading":"gù","description":"gù：古代拘在罪人两手的刑具桎～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梏"},{"id":"glyph-seal-6893","script":"seal","character":"梓","reading":"zǐ","description":"zǐ：(1)落叶乔木。木材可供建筑及制造器物之用～器（棺材）。～宫（皇帝的棺材）。\n(2)治木器～人（古代制造器具的木工）。～匠。\n(3)木头雕刻成印刷用的木板付～（把稿件交付排印）。～行（xíng）。\n(4)指故里～里。桑～。\n(5)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梓"},{"id":"glyph-seal-6897","script":"seal","character":"梗","reading":"gěng","description":"gěng：(1)植物的枝或茎菜～子。\n(2)直，挺立～着脖子。\n(3)正直，直爽～直。\n(4)阻塞，妨碍～塞（sè）。～阻。心肌～死。\n(5)大略～概。\n(6)有刺的草木～榆（刺榆）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梗"},{"id":"glyph-seal-68a2","script":"seal","character":"梢","reading":"shāo；sào","description":"shāo：(1)树枝或条状物的末端树～。末～。～头。～林。\n(2)末尾眉～。收～。\n(3)古代奏乐时拿的竿子。\n(4)古同艄”，船舵尾。\nsào：(1)像圆锥体的形状。\n(2)柱形物体的横剖面向一端面逐渐缩小的形式。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梢"},{"id":"glyph-seal-68a6","script":"seal","character":"梦","reading":"mèng","description":"⒈睡眠时局部大脑皮层还未停止活动，因体内、外各种刺激而引起大脑内的表现影像日有所思，夜有所～。\n⒉指做梦～见。～游。\n⒊〈喻〉虚幻～幻。～想。～求。\n梦méng 1.不明。 2.昏乱。见\"梦梦\"。 3.最细的雨。 4.用同\"蒙\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梦"}];
